rpc CreateReportReason(ReportReason) returns (ReportReason) {
    option (google.api.http) = {
        post: "/v2/social/report-reason"
        body: "*"
    };
}
rpc UpdateReportReason(ReportReason) returns (ReportReason) {
    option (google.api.http) = {
        put: "/v2/social/report-reason/{id}"
        body: "*"
    };
}
rpc DeleteReportReason(ReportReason) returns (ReportReason) {
    option (google.api.http) = {
        delete: "/v2/social/report-reason/{id}"
    };
}
